//! Bucket storage and neighborhood bookkeeping for the hopscotch table.
//!
//! A bucket is one slot of the (power-of-two sized) bucket array together with
//! the two pieces of metadata that make hopscotch hashing work. Both live in a
//! single `u64` (`info`):
//!
//! * bits `0 ..= NEIGHBORHOOD_SIZE-1` are the *neighborhood bitmap* of this
//!   bucket **acting as a home bucket**: bit `j` is set iff slot
//!   `self_index + j` currently holds an entry whose home bucket is
//!   `self_index`. The bitmap therefore talks about a window of slots starting
//!   at this one -- it says nothing about who owns this slot's own `entry`.
//! * bit `NEIGHBORHOOD_SIZE` is the `has_overflow` flag: set iff at least one
//!   entry whose home bucket is `self_index` currently lives in the map's
//!   overflow list.
//!
//! `entry` is the key/value pair physically stored in this slot, if any. Its
//! owner (home bucket) is some bucket in
//! `[self_index - (NEIGHBORHOOD_SIZE - 1), self_index]`.

#![allow(dead_code)]

/// Number of slots in a bucket's neighborhood: an entry is always stored at
/// offset `0 ..= NEIGHBORHOOD_SIZE-1` from its home bucket, or else in the
/// overflow list. 62 keeps the bitmap and the overflow flag inside one `u64`,
/// matching the default neighborhood of `tsl::hopscotch_map`.
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// Mask selecting the neighborhood bitmap out of `Bucket::info`.
const NEIGHBORHOOD_MASK: u64 = (1u64 << NEIGHBORHOOD_SIZE) - 1;

/// The `has_overflow` bit of `Bucket::info`.
const OVERFLOW_FLAG: u64 = 1u64 << NEIGHBORHOOD_SIZE;

#[derive(Clone)]
pub struct Bucket<K, V> {
    /// Neighborhood bitmap + `has_overflow` flag, see the module docs.
    info: u64,
    /// The pair stored in this slot (not necessarily homed here).
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    #[inline]
    pub fn empty() -> Self {
        Bucket {
            info: 0,
            entry: None,
        }
    }

    /// True when no pair is physically stored in this slot. The metadata bits
    /// are independent of this and may well be non-zero.
    #[inline]
    pub fn is_free(&self) -> bool {
        self.entry.is_none()
    }

    #[inline]
    pub fn is_occupied(&self) -> bool {
        self.entry.is_some()
    }

    #[inline]
    pub fn entry(&self) -> Option<&(K, V)> {
        self.entry.as_ref()
    }

    #[inline]
    pub fn entry_mut(&mut self) -> Option<&mut (K, V)> {
        self.entry.as_mut()
    }

    #[inline]
    pub fn key(&self) -> Option<&K> {
        self.entry.as_ref().map(|(k, _)| k)
    }

    /// Store a pair in a slot that must currently be free.
    #[inline]
    pub fn set_entry(&mut self, key: K, value: V) {
        debug_assert!(self.is_free(), "overwriting an occupied bucket");
        self.entry = Some((key, value));
    }

    #[inline]
    pub fn take_entry(&mut self) -> Option<(K, V)> {
        self.entry.take()
    }

    /// The raw neighborhood bitmap (overflow flag masked off).
    #[inline]
    pub fn neighbors(&self) -> u64 {
        self.info & NEIGHBORHOOD_MASK
    }

    #[inline]
    pub fn has_neighbor(&self, offset: usize) -> bool {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        self.info & (1u64 << offset) != 0
    }

    #[inline]
    pub fn set_neighbor(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        debug_assert!(!self.has_neighbor(offset), "neighborhood bit set twice");
        self.info |= 1u64 << offset;
    }

    #[inline]
    pub fn clear_neighbor(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        debug_assert!(self.has_neighbor(offset), "clearing an unset neighborhood bit");
        self.info &= !(1u64 << offset);
    }

    #[inline]
    pub fn has_overflow(&self) -> bool {
        self.info & OVERFLOW_FLAG != 0
    }

    #[inline]
    pub fn set_overflow(&mut self) {
        self.info |= OVERFLOW_FLAG;
    }

    #[inline]
    pub fn clear_overflow(&mut self) {
        self.info &= !OVERFLOW_FLAG;
    }

    /// Drop the metadata bits, keeping any stored pair untouched.
    #[inline]
    pub fn clear_info(&mut self) {
        self.info = 0;
    }

    /// Back to the pristine state: no pair, no metadata.
    #[inline]
    pub fn reset(&mut self) {
        self.info = 0;
        self.entry = None;
    }
}

//! A from-scratch hopscotch hash map, modelled on `tsl::hopscotch_map`.
//!
//! # Layout
//!
//! The table is a `Vec<Bucket>` of `bucket_count + NEIGHBORHOOD_SIZE - 1`
//! slots, where `bucket_count` is a power of two (or `0` for a brand new map
//! that has not allocated yet). A key's *home bucket* is
//! `hash(key) & (bucket_count - 1)`, so home indices only ever fall in
//! `0 .. bucket_count`; the extra `NEIGHBORHOOD_SIZE - 1` tail slots let every
//! neighborhood be a plain forward window with no wrap-around arithmetic.
//!
//! # Invariants
//!
//! 1. An entry lives either in a bucket at offset `0 ..= NEIGHBORHOOD_SIZE-1`
//!    from its home bucket, or in `overflow`.
//! 2. `buckets[h].neighbors()` has bit `j` set **iff** `buckets[h + j]` holds an
//!    entry whose home bucket is `h`. Consequently a set bit always points at
//!    an occupied slot, and every occupied slot is pointed at by exactly one
//!    bit of exactly one home bucket.
//! 3. `buckets[h].has_overflow()` is set **iff** some entry in `overflow` has
//!    home bucket `h`.
//! 4. `len == (number of occupied buckets) + overflow.len()`.
//!
//! Invariants 2 and 3 are what make lookups cheap: a hit is decided by probing
//! only the set bits of the home neighborhood plus, when the flag says so, the
//! overflow list.
//!
//! `assert_invariants` re-derives all of them from scratch and is used by the
//! test-suite.

#![allow(dead_code)]

use std::borrow::Borrow;
use std::collections::hash_map::RandomState;
use std::fmt;
use std::hash::{BuildHasher, Hash, Hasher};
use std::iter::FusedIterator;
use std::ops::Index;

use super::bucket::{Bucket, NEIGHBORHOOD_SIZE};

/// Smallest table we ever allocate.
const MIN_BUCKET_COUNT: usize = 16;

/// `tsl::hopscotch_map`'s default `max_load_factor()`.
const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.5;

/// Upper bound for the "grow instead of overflowing" retry loop in `rehash_to`,
/// so a pathological hasher degrades into a longer overflow list instead of
/// looping forever.
const MAX_RETRY_BUCKET_COUNT: usize = 1 << 30;

#[inline]
fn hash_key<S, Q>(hash_builder: &S, key: &Q) -> u64
where
    S: BuildHasher,
    Q: Hash + ?Sized,
{
    let mut hasher = hash_builder.build_hasher();
    key.hash(&mut hasher);
    hasher.finish()
}

/// Home bucket of a hash for a table of `bucket_count` (power of two) buckets.
#[inline]
fn home_of(hash: u64, bucket_count: usize) -> usize {
    debug_assert!(bucket_count.is_power_of_two());
    (hash & (bucket_count as u64 - 1)) as usize
}

fn threshold_for(bucket_count: usize, max_load_factor: f32) -> usize {
    if bucket_count == 0 {
        return 0;
    }
    let t = (bucket_count as f64 * max_load_factor as f64) as usize;
    t.max(1)
}

/// Where a located key physically lives.
#[derive(Clone, Copy)]
enum Slot {
    /// Bucket `home + offset`, owned by home bucket `home`.
    Bucket { home: usize, offset: usize },
    /// Index into the overflow list.
    Overflow(usize),
}

/// Outcome of an insertion attempt.
enum Insertion<V> {
    /// The pair was stored and `len` grew by one.
    Inserted,
    /// An equal key was already present. `previous` carries the replaced value
    /// only when the caller asked for assignment.
    Present { previous: Option<V> },
}

/// A hash map implemented with hopscotch hashing.
pub struct HopscotchMap<K, V, S = RandomState> {
    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots, or empty when
    /// `bucket_count == 0`.
    buckets: Vec<Bucket<K, V>>,
    /// Entries that could not be placed inside their neighborhood.
    overflow: Vec<(K, V)>,
    hash_builder: S,
    /// Power of two, or 0 before the first allocation.
    bucket_count: usize,
    len: usize,
    max_load_factor: f32,
    /// Cached `bucket_count * max_load_factor`; growth trigger.
    load_threshold: usize,
}

impl<K, V> HopscotchMap<K, V, RandomState> {
    /// An empty map that has not allocated a table yet.
    pub fn new() -> Self {
        Self::with_hasher(RandomState::new())
    }

    /// An empty map sized so that `capacity` insertions do not rehash.
    pub fn with_capacity(capacity: usize) -> Self {
        Self::with_capacity_and_hasher(capacity, RandomState::new())
    }
}

impl<K, V, S> HopscotchMap<K, V, S> {
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchMap {
            buckets: Vec::new(),
            overflow: Vec::new(),
            hash_builder,
            bucket_count: 0,
            len: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            load_threshold: 0,
        }
    }

    /// Number of stored elements (`tsl::hopscotch_map::size`).
    #[inline]
    pub fn len(&self) -> usize {
        self.len
    }

    /// Alias of [`len`](Self::len), spelled like the C++ member.
    #[inline]
    pub fn size(&self) -> usize {
        self.len
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Number of home buckets (always a power of two, or 0 while unallocated).
    #[inline]
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    /// How many entries currently sit in the overflow list.
    #[inline]
    pub fn overflow_len(&self) -> usize {
        self.overflow.len()
    }

    #[inline]
    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.len as f32 / self.bucket_count as f32
        }
    }

    #[inline]
    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    #[inline]
    pub fn hasher(&self) -> &S {
        &self.hash_builder
    }

    /// Remove every element, keeping the allocated table.
    pub fn clear(&mut self) {
        for bucket in &mut self.buckets {
            bucket.reset();
        }
        self.overflow.clear();
        self.len = 0;
    }

    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter {
            buckets: self.buckets.iter(),
            overflow: self.overflow.iter(),
            remaining: self.len,
        }
    }

    pub fn iter_mut(&mut self) -> IterMut<'_, K, V> {
        IterMut {
            buckets: self.buckets.iter_mut(),
            overflow: self.overflow.iter_mut(),
            remaining: self.len,
        }
    }

    pub fn keys(&self) -> Keys<'_, K, V> {
        Keys { inner: self.iter() }
    }

    pub fn values(&self) -> Values<'_, K, V> {
        Values { inner: self.iter() }
    }

    pub fn values_mut(&mut self) -> ValuesMut<'_, K, V> {
        ValuesMut {
            inner: self.iter_mut(),
        }
    }

    /// Beyond this many overflow entries, growing beats scanning.
    fn overflow_limit_for(bucket_count: usize) -> usize {
        8 + bucket_count / 64
    }

    /// Pull every entry out of the table, leaving it metadata-clean and empty.
    fn drain_entries(&mut self) -> Vec<(K, V)> {
        let mut entries = Vec::with_capacity(self.len);
        for bucket in &mut self.buckets {
            if let Some(entry) = bucket.take_entry() {
                entries.push(entry);
            }
            bucket.clear_info();
        }
        entries.append(&mut self.overflow);
        self.len = 0;
        entries
    }

    /// Install a fresh, empty table of `bucket_count` buckets.
    fn reset_table(&mut self, bucket_count: usize) {
        debug_assert!(bucket_count.is_power_of_two());
        self.buckets = std::iter::repeat_with(Bucket::empty)
            .take(bucket_count + NEIGHBORHOOD_SIZE - 1)
            .collect();
        self.overflow.clear();
        self.bucket_count = bucket_count;
        self.len = 0;
        self.load_threshold = threshold_for(bucket_count, self.max_load_factor);
    }

    /// Move the free slot at `free` closer to the front by hopping one entry
    /// forward into it. Returns the index of the newly freed slot, or `None`
    /// when no entry may legally be displaced (a failed hopscotch move).
    fn hop_free_slot_closer(&mut self, free: usize) -> Option<usize> {
        // Only home buckets within `NEIGHBORHOOD_SIZE - 1` slots before `free`
        // can own an entry that is still inside its neighborhood after moving
        // to `free`. Scanning them front-to-back tries the biggest hop first.
        let first = free + 1 - NEIGHBORHOOD_SIZE;
        for candidate in first..free {
            let bits = self.buckets[candidate].neighbors();
            if bits == 0 {
                continue;
            }
            // Its closest entry gives the largest jump backwards.
            let offset = bits.trailing_zeros() as usize;
            let victim = candidate + offset;
            if victim >= free {
                // Everything this bucket owns already sits at or past `free`.
                continue;
            }
            let (key, value) = self.buckets[victim]
                .take_entry()
                .expect("neighborhood bit without an entry");
            self.buckets[free].set_entry(key, value);
            self.buckets[candidate].clear_neighbor(offset);
            self.buckets[candidate].set_neighbor(free - candidate);
            return Some(victim);
        }
        None
    }

    /// Try to store a brand new pair inside the bucket array. On failure the
    /// pair is handed back so the caller can put it in the overflow list.
    fn try_place_in_buckets(
        &mut self,
        home: usize,
        key: K,
        value: V,
    ) -> Result<(), (K, V)> {
        // Linear probe for the first free slot at or after the home bucket.
        let mut free = match (home..self.buckets.len()).find(|&i| self.buckets[i].is_free()) {
            Some(i) => i,
            None => return Err((key, value)),
        };
        // Hop it back until it lands inside the home neighborhood.
        while free - home >= NEIGHBORHOOD_SIZE {
            match self.hop_free_slot_closer(free) {
                Some(next) => free = next,
                None => return Err((key, value)),
            }
        }
        self.buckets[free].set_entry(key, value);
        self.buckets[home].set_neighbor(free - home);
        Ok(())
    }

    fn push_overflow(&mut self, home: usize, key: K, value: V) {
        self.overflow.push((key, value));
        self.buckets[home].set_overflow();
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> Self {
        let mut map = Self::with_hasher(hash_builder);
        map.reserve(capacity);
        map
    }

    #[inline]
    fn hash_of<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        hash_key(&self.hash_builder, key)
    }

    /// Find where `key` lives, probing only the set bits of its home
    /// neighborhood and then the overflow list if the home flag says so.
    fn locate<Q>(&self, hash: u64, key: &Q) -> Option<Slot>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }
        let home = home_of(hash, self.bucket_count);
        let mut bits = self.buckets[home].neighbors();
        while bits != 0 {
            let offset = bits.trailing_zeros() as usize;
            bits &= bits - 1;
            match self.buckets[home + offset].entry() {
                Some((k, _)) if k.borrow() == key => {
                    return Some(Slot::Bucket { home, offset });
                }
                Some(_) => {}
                None => debug_assert!(false, "neighborhood bit without an entry"),
            }
        }
        if self.buckets[home].has_overflow() {
            // Any overflow entry with an equal key necessarily has this same
            // home bucket, so matching on the key alone is enough.
            for (i, (k, _)) in self.overflow.iter().enumerate() {
                if k.borrow() == key {
                    return Some(Slot::Overflow(i));
                }
            }
        }
        None
    }

    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        match self.locate(hash, key)? {
            Slot::Bucket { home, offset } => {
                self.buckets[home + offset].entry().map(|(_, v)| v)
            }
            Slot::Overflow(i) => Some(&self.overflow[i].1),
        }
    }

    pub fn get_key_value<Q>(&self, key: &Q) -> Option<(&K, &V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        match self.locate(hash, key)? {
            Slot::Bucket { home, offset } => {
                self.buckets[home + offset].entry().map(|(k, v)| (k, v))
            }
            Slot::Overflow(i) => {
                let (k, v) = &self.overflow[i];
                Some((k, v))
            }
        }
    }

    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        match self.locate(hash, key)? {
            Slot::Bucket { home, offset } => {
                self.buckets[home + offset].entry_mut().map(|(_, v)| v)
            }
            Slot::Overflow(i) => Some(&mut self.overflow[i].1),
        }
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        self.locate(hash, key).is_some()
    }

    /// `map.insert((k, v))`, reading like the C++ `map.insert({k, v})`:
    /// an existing equal key is left untouched. Returns whether it was stored.
    pub fn insert(&mut self, pair: (K, V)) -> bool {
        let (key, value) = pair;
        matches!(
            self.insert_internal(key, value, false),
            Insertion::Inserted
        )
    }

    /// Spelled-out alias of [`insert`](Self::insert).
    pub fn insert_pair(&mut self, pair: (K, V)) -> bool {
        self.insert(pair)
    }

    /// Two-argument form of [`insert`](Self::insert).
    pub fn insert_kv(&mut self, key: K, value: V) -> bool {
        matches!(
            self.insert_internal(key, value, false),
            Insertion::Inserted
        )
    }

    /// C++17 `insert_or_assign`: overwrite on collision, returning the old
    /// value (`None` when the key is new).
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        match self.insert_internal(key, value, true) {
            Insertion::Inserted => None,
            Insertion::Present { previous } => previous,
        }
    }

    fn insert_internal(&mut self, key: K, value: V, assign: bool) -> Insertion<V> {
        if self.bucket_count == 0 {
            self.reset_table(MIN_BUCKET_COUNT);
        }
        let hash = self.hash_of(&key);
        if let Some(slot) = self.locate(hash, &key) {
            if !assign {
                return Insertion::Present { previous: None };
            }
            let previous = match slot {
                Slot::Bucket { home, offset } => {
                    let entry = self.buckets[home + offset]
                        .entry_mut()
                        .expect("neighborhood bit without an entry");
                    std::mem::replace(&mut entry.1, value)
                }
                Slot::Overflow(i) => std::mem::replace(&mut self.overflow[i].1, value),
            };
            return Insertion::Present {
                previous: Some(previous),
            };
        }
        // A genuinely new key: make room first, since growing moves everything.
        if self.len + 1 > self.load_threshold
            || self.overflow.len() > Self::overflow_limit_for(self.bucket_count)
        {
            self.rehash_to(self.bucket_count.saturating_mul(2));
        }
        let home = home_of(hash, self.bucket_count);
        match self.try_place_in_buckets(home, key, value) {
            Ok(()) => {}
            Err((key, value)) => self.push_overflow(home, key, value),
        }
        self.len += 1;
        Insertion::Inserted
    }

    /// Remove `key`, returning its value.
    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.remove_entry(key).map(|(_, v)| v)
    }

    /// Remove `key`, returning the whole pair.
    pub fn remove_entry<Q>(&mut self, key: &Q) -> Option<(K, V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash_of(key);
        let slot = self.locate(hash, key)?;
        let entry = match slot {
            Slot::Bucket { home, offset } => {
                let entry = self.buckets[home + offset]
                    .take_entry()
                    .expect("neighborhood bit without an entry");
                self.buckets[home].clear_neighbor(offset);
                entry
            }
            Slot::Overflow(i) => {
                let home = home_of(hash, self.bucket_count);
                let entry = self.overflow.swap_remove(i);
                // Keep invariant 3 exact: the flag stays only while some other
                // overflow entry is still homed at `home`.
                let bucket_count = self.bucket_count;
                let hash_builder = &self.hash_builder;
                let still_overflowing = self
                    .overflow
                    .iter()
                    .any(|(k, _)| home_of(hash_key(hash_builder, k), bucket_count) == home);
                if !still_overflowing {
                    self.buckets[home].clear_overflow();
                }
                entry
            }
        };
        self.len -= 1;
        Some(entry)
    }

    /// `tsl::hopscotch_map::erase(const key_type&)`: the number of elements
    /// removed, i.e. 0 or 1.
    pub fn erase<Q>(&mut self, key: &Q) -> usize
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.remove(key) {
            Some(_) => 1,
            None => 0,
        }
    }

    /// Grow (or shrink-to-fit-the-request) the table to at least `requested`
    /// buckets and reinsert everything.
    fn rehash_to(&mut self, requested: usize) {
        let mut bucket_count = requested.max(MIN_BUCKET_COUNT).next_power_of_two();
        let mut entries = self.drain_entries();
        loop {
            self.reset_table(bucket_count);
            let mut leftovers = Vec::new();
            for (key, value) in entries.drain(..) {
                let home = home_of(hash_key(&self.hash_builder, &key), bucket_count);
                match self.try_place_in_buckets(home, key, value) {
                    Ok(()) => self.len += 1,
                    Err(pair) => leftovers.push(pair),
                }
            }
            // Overflowing is correct but slows lookups down, so prefer a bigger
            // table while the leftovers are more than a rounding error.
            if leftovers.len() <= Self::overflow_limit_for(bucket_count)
                || bucket_count >= MAX_RETRY_BUCKET_COUNT
            {
                for (key, value) in leftovers {
                    let home = home_of(hash_key(&self.hash_builder, &key), bucket_count);
                    self.push_overflow(home, key, value);
                    self.len += 1;
                }
                return;
            }
            entries = self.drain_entries();
            entries.extend(leftovers);
            bucket_count *= 2;
        }
    }

    /// Make room for `additional` more elements without rehashing.
    pub fn reserve(&mut self, additional: usize) {
        let target = self.len.saturating_add(additional);
        let needed = ((target as f64) / (self.max_load_factor as f64)).ceil() as usize;
        if needed > self.bucket_count {
            self.rehash_to(needed);
        }
    }

    /// Rebuild the table with at least `bucket_count` buckets.
    pub fn rehash(&mut self, bucket_count: usize) {
        let needed = ((self.len as f64) / (self.max_load_factor as f64)).ceil() as usize;
        self.rehash_to(bucket_count.max(needed).max(1));
    }

    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        assert!(
            max_load_factor > 0.0 && max_load_factor <= 0.95,
            "max_load_factor must be in (0, 0.95]"
        );
        self.max_load_factor = max_load_factor;
        self.load_threshold = threshold_for(self.bucket_count, max_load_factor);
        if self.bucket_count > 0 && self.len > self.load_threshold {
            self.rehash_to(self.bucket_count * 2);
        }
    }

    /// Re-derive every invariant from the raw storage. Panics on any breach.
    /// Intended for tests; `O(bucket_count + overflow^2)`.
    pub fn assert_invariants(&self) {
        if self.bucket_count == 0 {
            assert!(self.buckets.is_empty(), "unallocated map with buckets");
            assert!(self.overflow.is_empty(), "unallocated map with overflow");
            assert_eq!(self.len, 0, "unallocated map with elements");
            return;
        }
        assert!(self.bucket_count.is_power_of_two(), "bucket_count not a power of two");
        assert_eq!(
            self.buckets.len(),
            self.bucket_count + NEIGHBORHOOD_SIZE - 1,
            "bucket array has the wrong length"
        );

        // Invariant 2: every set bit points at an occupied slot homed there,
        // and every occupied slot is claimed exactly once.
        let mut claimed = vec![false; self.buckets.len()];
        let mut claimed_count = 0usize;
        for home in 0..self.bucket_count {
            let mut bits = self.buckets[home].neighbors();
            while bits != 0 {
                let offset = bits.trailing_zeros() as usize;
                bits &= bits - 1;
                let slot = home + offset;
                let (key, _) = self.buckets[slot]
                    .entry()
                    .unwrap_or_else(|| panic!("bucket {home} claims empty slot {slot}"));
                assert_eq!(
                    home_of(self.hash_of(key), self.bucket_count),
                    home,
                    "bucket {home} claims slot {slot} homed elsewhere"
                );
                assert!(!claimed[slot], "slot {slot} claimed twice");
                claimed[slot] = true;
                claimed_count += 1;
            }
        }
        // Tail slots have no bitmap of their own; make sure nothing set one.
        for slot in self.bucket_count..self.buckets.len() {
            assert_eq!(
                self.buckets[slot].neighbors(),
                0,
                "overflow-area slot {slot} carries a neighborhood"
            );
            assert!(
                !self.buckets[slot].has_overflow(),
                "overflow-area slot {slot} carries the overflow flag"
            );
        }
        let occupied = self.buckets.iter().filter(|b| b.is_occupied()).count();
        assert_eq!(occupied, claimed_count, "occupied slots not all claimed");
        for (slot, bucket) in self.buckets.iter().enumerate() {
            assert_eq!(
                bucket.is_occupied(),
                claimed[slot],
                "slot {slot} occupancy disagrees with the bitmaps"
            );
        }

        // Invariant 3: overflow flags are exact.
        let mut expected_flags = vec![false; self.bucket_count];
        for (key, _) in &self.overflow {
            expected_flags[home_of(self.hash_of(key), self.bucket_count)] = true;
        }
        for home in 0..self.bucket_count {
            assert_eq!(
                self.buckets[home].has_overflow(),
                expected_flags[home],
                "bucket {home} has a stale overflow flag"
            );
        }

        // Invariant 4 plus key uniqueness.
        assert_eq!(occupied + self.overflow.len(), self.len, "len is stale");
        let mut keys: Vec<&K> = self.keys().collect();
        assert_eq!(keys.len(), self.len, "iterator yields the wrong count");
        keys.sort_by_key(|k| self.hash_of(k));
        for window in keys.windows(2) {
            if self.hash_of(window[0]) == self.hash_of(window[1]) {
                assert!(window[0] != window[1], "duplicate key stored twice");
            }
        }
    }
}

