//! Faithful re-implementation of `std::stoi` as libstdc++ implements it.
//!
//! libstdc++ builds `std::stoi` on top of `strtol`, so the accepted grammar is
//!
//! ```text
//!     [white-space]* [+|-] [0-9]+ <anything, ignored>
//! ```
//!
//! and the two failure modes are
//!
//! * no digits were converted at all -> `std::invalid_argument("stoi")`
//! * the converted value does not fit in an `int` (or `strtol` itself set
//!   `ERANGE`) -> `std::out_of_range("stoi")`
//!
//! Both failures propagate out of `main` uncaught, so the process dies through
//! `std::terminate`; see [`super::terminate`].

#![allow(dead_code)]

use super::terminate;

/// Once the accumulator passes this, the result cannot possibly fit in an
/// `int`, so we stop accumulating (and thus never overflow `i64`) and just
/// remember that the value is out of range -- exactly the observable behaviour
/// of `strtol` reporting `ERANGE`.
const SATURATION_GUARD: i64 = 1_000_000_000_000;

/// The C locale's `isspace`.
#[inline]
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// `std::stoi(str)` over raw bytes. Never returns on the error paths: it
/// reproduces the C++ abort instead.
pub fn stoi(text: &[u8]) -> i32 {
    let mut i = 0;
    while i < text.len() && is_space(text[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < text.len() && (text[i] == b'+' || text[i] == b'-') {
        negative = text[i] == b'-';
        i += 1;
    }

    let digits_start = i;
    let mut magnitude: i64 = 0;
    let mut saturated = false;
    while i < text.len() && text[i].is_ascii_digit() {
        if !saturated {
            magnitude = magnitude * 10 + i64::from(text[i] - b'0');
            if magnitude > SATURATION_GUARD {
                saturated = true;
            }
        }
        i += 1;
    }

    // "no conversion could be performed"
    if i == digits_start {
        terminate::throw_invalid_argument("stoi");
    }

    let value = if negative { -magnitude } else { magnitude };
    if saturated || value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        terminate::throw_out_of_range("stoi");
    }
    value as i32
}

/// Convenience wrapper for `&str` callers.
pub fn stoi_str(text: &str) -> i32 {
    stoi(text.as_bytes())
}

//! Reproduction of what a C++ program does when an exception escapes `main`.
//!
//! libstdc++'s verbose terminate handler prints, on stderr,
//!
//! ```text
//! terminate called after throwing an instance of '<mangled-demangled type>'
//!   what():  <what()>
//! ```
//!
//! (note the *two* spaces after `what():`) and then calls `abort()`, so the
//! process dies from `SIGABRT` and a shell reports exit status 134. Nothing is
//! written to stdout on this path.

#![allow(dead_code)]

use std::io::{self, Write};
use std::process;

/// Print the verbose-terminate message for an exception of type
/// `exception_type` whose `what()` is `what`, then die from `SIGABRT`.
pub fn terminate(exception_type: &str, what: &str) -> ! {
    let message = format!(
        "terminate called after throwing an instance of '{exception_type}'\n  what():  {what}\n"
    );
    let mut stderr = io::stderr();
    let _ = stderr.write_all(message.as_bytes());
    let _ = stderr.flush();
    process::abort()
}

/// `throw std::invalid_argument(what);` escaping `main`.
pub fn throw_invalid_argument(what: &str) -> ! {
    terminate("std::invalid_argument", what)
}

/// `throw std::out_of_range(what);` escaping `main`.
pub fn throw_out_of_range(what: &str) -> ! {
    terminate("std::out_of_range", what)
}

/// `throw std::logic_error(what);` escaping `main`.
pub fn throw_logic_error(what: &str) -> ! {
    terminate("std::logic_error", what)
}

//! Small C++ standard-library compatibility layer.
//!
//! The port has to match the reference binary byte for byte, including on the
//! paths where the C++ program dies from an uncaught exception. This module
//! provides the two pieces `main` needs:
//!
//! * [`stoi`] -- libstdc++'s `std::stoi` grammar and its two throwing paths;
//! * [`terminate`] -- the verbose-terminate message plus `abort()`.
//!
//! It also carries [`argv`], which hands `main` the argument vector as raw
//! bytes (that is what `char* argv[]` really is), and [`string_from_c_str`],
//! which models `std::string(const char*)` refusing a null pointer.

#![allow(dead_code)]

pub mod stoi;
pub mod terminate;

pub use stoi::{stoi, stoi_str};
pub use terminate::{terminate, throw_invalid_argument, throw_logic_error, throw_out_of_range};

/// The process argument vector as byte strings, `argv[0]` included, so that
/// `argv.len()` is C's `argc` and comparisons are byte-exact like
/// `std::string(argv[1]) == "--a"`.
#[cfg(unix)]
pub fn argv() -> Vec<Vec<u8>> {
    use std::os::unix::ffi::OsStrExt;
    std::env::args_os()
        .map(|arg| arg.as_bytes().to_vec())
        .collect()
}

/// Non-unix fallback: no byte-oriented `OsStr` view is available in std, so
/// approximate it with a lossy conversion.
#[cfg(not(unix))]
pub fn argv() -> Vec<Vec<u8>> {
    std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned().into_bytes())
        .collect()
}

/// `std::string(const char*)`: constructing a `std::string` from a null pointer
/// throws `std::logic_error("basic_string::_S_construct null not valid")`.
/// `None` stands for the null pointer C's `argv` is terminated with, i.e. for
/// reading `argv[i]` with `i >= argc`.
pub fn string_from_c_str(pointer: Option<&[u8]>) -> &[u8] {
    match pointer {
        Some(bytes) => bytes,
        None => terminate::throw_logic_error("basic_string::_S_construct null not valid"),
    }
}

