//! Direct translation of `hopscotch-map/tests/test5.cpp`:
//!
//! ```cpp
//! int main(int argc, char* argv[]) {
//!     int count = 5;
//!     if (argc > 1 && std::string(argv[1]) == "--a") {
//!         count = std::stoi(argv[2]);
//!     }
//!
//!     tsl::hopscotch_map<int, int> map;
//!     for (int i = 0; i < count; i++) {
//!         map.insert({i, i * 2});
//!     }
//!
//!     int removed = 0;
//!     for (int i = 0; i < count; i += 2) {
//!         removed += map.erase(i);
//!     }
//!
//!     std::cout << map.size() << " " << removed << std::endl;
//!
//!     return 0;
//! }
//! ```
//!
//! The module files are pulled in with `#[path]` so this file builds both
//! standalone (`rustc -O test5.rs -o test5`) and as the crate's `[[bin]]`
//! target (`cargo build --release`).

#[path = "src/cpp_compat/mod.rs"]
mod cpp_compat;
#[path = "src/hopscotch/mod.rs"]
mod hopscotch;

use std::io::{self, Write};

use hopscotch::HopscotchMap;

fn main() {
    let argv = cpp_compat::argv();
    let argc = argv.len();

    let mut count: i32 = 5;
    if argc > 1 && argv[1] == b"--a" {
        // `std::stoi(argv[2])` first builds a std::string from argv[2]; when
        // only "--a" was passed that pointer is null and the construction
        // throws std::logic_error before stoi ever runs.
        let text = cpp_compat::string_from_c_str(argv.get(2).map(Vec::as_slice));
        count = cpp_compat::stoi(text);
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    // Loop counters are widened to i64 so that the Rust port cannot overflow
    // where C++ would merely be undefined; every reachable value is identical.
    let mut i: i64 = 0;
    while i < i64::from(count) {
        let key = i as i32;
        map.insert((key, key.wrapping_mul(2)));
        i += 1;
    }

    let mut removed: i32 = 0;
    let mut i: i64 = 0;
    while i < i64::from(count) {
        removed += map.erase(&(i as i32)) as i32;
        i += 2;
    }

    // `std::cout << ... << std::endl` -- newline plus a flush.
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let _ = writeln!(out, "{} {}", map.size(), removed);
    let _ = out.flush();
}

